function packPriority(parts, budget, reserve) {
  const sorted = parts.map((part, index) => ({ ...part, index }))
    .sort((a, b) => a.priority - b.priority || a.index - b.index);
  const included = [];
  const excluded = [];
  let used = 0;
  for (const part of sorted) {
    if (used + part.tokens <= budget - reserve) {
      included.push(part.id);
      used += part.tokens;
    } else {
      excluded.push(part.id);
    }
  }
  return { included, excluded, used };
}

