function selectFiles(files, needed) {
  const wanted = new Set(needed);
  const available = new Set(files.map(file => file.path));
  return {
    included: files.filter(file => wanted.has(file.path)).map(file => file.path),
    missing: [...wanted].filter(path => !available.has(path))
  };
}

