function retrievePaths(query, files, k) {
  if (!Number.isInteger(k) || k <= 0 || !query.trim()) return [];
  const words = [...new Set(query.trim().toLowerCase().split(/\s+/))];
  return files.map((file, index) => {
    const tokens = new Set(file.text.toLowerCase().split(/\s+/));
    return { path: file.path, index, score: words.filter(word => tokens.has(word)).length };
  }).filter(file => file.score > 0)
    .sort((a, b) => b.score - a.score || a.index - b.index)
    .slice(0, k).map(file => file.path);
}

