function sourceAnswer(question, chunks) {
  const words = [...new Set(question.trim().toLowerCase().split(/\s+/).filter(Boolean))];
  let best = null;
  let bestScore = 0;
  for (const chunk of chunks) {
    const tokens = new Set(chunk.text.toLowerCase().split(/\s+/));
    const score = words.filter(word => tokens.has(word)).length;
    if (score > bestScore) { best = chunk; bestScore = score; }
  }
  return best ? { text: best.text, sourceId: best.id } : null;
}

